entries[1230477] = { ["name"] = "Prismatic Focusing Iris", ["text"] = "2 sec cast\nTools: Jeweler's Tools\nReagents:\nSin'dorei Lens (2), Glimmering Gemdust (2)\nOptional Reagents:\nDrop:\nLothraxion\nZone:\nNexus-Point Xenas\n\nPrismatic Focusing Iris\nOptional Crafting Reagent\n+15 Recipe Difficulty\nProvides the following property: Your spells and abilities have a chance to activate the Iris, firing a focused beam of light at your target and dealing ( 1 * 1102 ) Arcane damage every second for 4 sec.\n\nEach unique gem color you have socketed empowers the Iris, causing it to deal 1% additional damage per.\nUsable with: Midnight recipes for most unembellished equipment.\n\"Can be bought and sold on the Auction House.\"" }
entries[1230478] = { ["name"] = "Stabilizing Gemstone Bandolier", ["text"] = "2 sec cast\nTools: Jeweler's Tools\nReagents:\nSanguine Garnet , Amani Lapis , Tenebrous Amethyst , Harandar Peridot , Glimmering Gemdust (3)\nOptional Reagents:\nDrop:\nHeavy Trunk\nZone:\nDelves\n\nStabilizing Gemstone Bandolier\nOptional Crafting Reagent\n+15 Recipe Difficulty\nProvides the following property: Double the gems, double the power!\n\nAll Jewelcrafting embellishments operate at double strength.\nUsable with: Midnight recipes for most unembellished equipment.\n\"Can be bought and sold on the Auction House.\"" }
entries[1230479] = { ["name"] = "Loa Worshiper's Band", ["text"] = "2 sec cast 3\nTools: Jeweler's Tools\nReagents:\nTormented Tantalum , Mote of Wild Magic (20), Kaleidoscopic Prism , Flawless Amani Lapis , Dusk-Shrouded Stone (5), Spark (#500) (2)\nOptional Reagents:\nVendor:\nMagovu\nZone:\nZul'Aman\nCost:\n150\n1500\n\nLoa Worshiper's Band\nBinds when picked up\nUnique-EquippedFinger\n+8 Stamina\n+ 15 Critical Strike\n+ 11 Mastery\n\nPrismatic Socket\n\nEquip: Your damaging spells and abilities have a chance to charge the band, calling forth the avatar of a Loa to assist you in combat.\n\nEach unique socketed gem color in your gear allows for different Loa to be summoned. These effects range from dealing damage to your foes or granting you temporary power." }
