entries[1230760] = { ["name"] = "Refulgent Razorstone", ["text"] = "2 sec cast\nTools: Blacksmith Hammer\nReagents:\nLuminant Flux (15), Petrified Root (2), Refulgent Copper Ingot (12), Dusk-Shrouded Stone (4)\nOptional Reagents:\nProfession Trainer:\nMidnight Blacksmithing (45)\nCost:\n210\n\nRefulgent Razorstone\n\nUse: Sharpen your Mining, Herbalism, or Skinning Tool, increasing Finesse by 43 for 2 hours." }
entries[1230761] = { ["name"] = "Refulgent Copper Ingot", ["text"] = "2 sec cast\nTools: Blacksmith Hammer\nReagents:\nLuminant Flux (2), Refulgent Copper Ore (5)\nOptional Reagents:\nProfession Trainer:\nMidnight Blacksmithing (1)\nCost:\n50\n\nRefulgent Copper Ingot\nCrafting Reagent\n\nProvides the following property: Refulgent Copper Ingot\n\"Smelted by players with the Blacksmithing skill. Can be bought and sold on the Auction House.\"" }
entries[1230762] = { ["name"] = "Gloaming Alloy", ["text"] = "2 sec cast\nTools: Blacksmith Hammer\nReagents:\nLuminant Flux (4), Umbral Tin Ore (6), Refulgent Copper Ingot (3)\nOptional Reagents:\nProfession Trainer:\nMidnight Blacksmithing (15)\nCost:\n140\n\nGloaming Alloy\nCrafting Reagent\n\nProvides the following property: Gloaming Alloy\n\"Smelted by players with the Blacksmithing skill. Can be bought and sold on the Auction House.\"" }
entries[1230763] = { ["name"] = "Sterling Alloy", ["text"] = "2 sec cast\nTools: Blacksmith Hammer\nReagents:\nLuminant Flux (4), Brilliant Silver Ore (6), Refulgent Copper Ingot (3)\nOptional Reagents:\nProfession Trainer:\nMidnight Blacksmithing (25)\nCost:\n160\n\nSterling Alloy\nCrafting Reagent\n\nProvides the following property: Sterling Alloy\n\"Smelted by players with the Blacksmithing skill. Can be bought and sold on the Auction House.\"" }
entries[1230764] = { ["name"] = "Refulgent Repair Hammer", ["text"] = "2 sec cast\nTools: Blacksmith Hammer\nReagents:\nLuminant Flux , Refulgent Copper Ingot , Dusk-Shrouded Stone\nOptional Reagents:\nProfession Trainer:\nMidnight Blacksmithing (5)\nCost:\n80\n\nRefulgent Repair Hammer\n\nUse: Fully repair a weapon or piece of plate armor (consumed on use).\n80\nRequires Midnight Blacksmithing\n(1)" }
entries[1230765] = { ["name"] = "Thalassian Master Repair Hammer", ["text"] = "8 sec cast\nTools: Blacksmith Hammer\nReagents:\nDazzling Thorium (3), Luminant Flux (10), Refulgent Copper Ingot (5), Sterling Alloy (5)\nProfession:\nArmorsmithing and Weaponsmithing Specialization Capstones\n\nThalassian Master Repair Hammer\nBinds when picked up\n\nUse: Repair a weapon or piece of plate armor you have specialized in repairing.\nRequires Midnight Blacksmithing\n(25)" }
entries[1230766] = { ["name"] = "Murder Row Fleet Feet", ["text"] = "2 sec cast 3\nTools: Blacksmith Hammer\nReagents:\nDazzling Thorium , Tormented Tantalum , Gloaming Alloy (10), Sterling Alloy (10), Silvermoon Weapon Wrap , Spark (#401) (2)\nOptional Reagents:\nDrop:\nLithiel Cinderfury\nZone:\nMurder Row\n\nMurder Row Fleet Feet\nBinds when picked up\nUnique-Equipped: Embellished (2)Feet Plate\n19 Armor\n+7 [Strength or Intellect]+10 Stamina\n+ 7 Random Stat 1\n+ 7 Random Stat 2\nDurability 80 / 80\nEquip: Your harmful spells and abilities have a chance to increase your Avoidance by 2 for 10 sec.\n90" }
entries[1230767] = { ["name"] = "Knight-Commander's Palisade", ["text"] = "2 sec cast 3\nTools: Blacksmith Hammer\nReagents:\nDazzling Thorium , Tormented Tantalum , Gloaming Alloy (10), Sterling Alloy (10), Silvermoon Weapon Wrap , Spark (#401) (2)\nOptional Reagents:\nDrop:\nGeneral Amias Bellamy\nZone:\nThe Voidspire\n\nKnight-Commander's Palisade\nBinds when picked up\nUnique-Equipped: Embellished (2)Off Hand Shield\n89 Armor\n222 Block\n+5 Strength\n+14 Intellect\n+7 Stamina\n+ 5 Random Stat 1\n+ 5 Random Stat 2\nDurability 120 / 120\nEquip: The light protects. There is a chance when you are attacked to gain Palisade's Protection , granting an absorption shield for 37 damage lasting 6 sec.\n\nShould the shield be breached before it expires, the magic of the shield will erupt with Palisade's Penance , dealing ( 1 * 37 ) Holy damage to nearby enemies.\n90" }
entries[1230768] = { ["name"] = "Murder Row Fishhook", ["text"] = "2 sec cast 3\nTools: Blacksmith Hammer\nReagents:\nDazzling Thorium , Tormented Tantalum , Gloaming Alloy (10), Sterling Alloy (10), Silvermoon Weapon Wrap , Spark (#401) (2)\nOptional Reagents:\nDrop:\nLithiel Cinderfury\nZone:\nMurder Row\n\nMurder Row Fishhook\nBinds when picked up\nOne-Hand Dagger\n6 - 12 Damage Speed 1.80\n(5.0 damage per second)\n+5 Agility\n+7 Stamina\n+ 5 Random Stat 1\n+ 5 Random Stat 2\nDurability 80 / 80\nEquip: Your harmful spells and abilities have a chance to bleed your target for ( 1 * 26 ) Physical damage every 2 over 10 sec.\n90" }
entries[1230769] = { ["name"] = "Sunforged Blacksmith's Hammer", ["text"] = "2 sec cast 3\nTools: Blacksmith Hammer\nReagents:\nMajestic Claw (2), Dazzling Thorium (2), Fused Vitality (20), Sterling Alloy (5)\nOptional Reagents:\nVendor:\nEriden\nZone:\nSilvermoon City\nCost:\n150\n\nVendor:\nLyrendal\nZone:\nSilvermoon City\nCost:\n150\n\nSunforged Blacksmith's Hammer\nBinds when picked up\nBlacksmithing Tool\n+ 48 Random Stat 1\nEquip: +18 Midnight Blacksmithing Skill\n78\nRequires Midnight Blacksmithing\n(1)" }
