entries[1230854] = { ["name"] = "Entropic Extract", ["text"] = "2 sec cast\nReagents:\nTranquility Bloom (3), Sunglass Vial (5)\nOptional Reagents:\nProfession Trainer:\nMidnight Alchemy (5)\nCost:\n125\n\nUse: Opens your mind to the touch of the Void. This effect enhances your appearance for 10 sec to 20 sec but has no bearing on your combat abilities.\n81\n\"Created by experienced alchemists. Can be bought and sold on the Auction House.\"" }
entries[1230855] = { ["name"] = "Composite Flora", ["text"] = "2 sec cast\nReagents:\nMote of Wild Magic (4), Mote of Primal Energy (4), Tranquility Bloom (6), Argentleaf (4)\nOptional Reagents:\nProfession Trainer:\nMidnight Alchemy (10)\nCost:\n125\n\nComposite Flora\nCrafting Reagent\n\nProvides the following property: Composite Flora\n\"Created by experienced alchemists. Can be bought and sold on the Auction House.\"" }
entries[1230856] = { ["name"] = "Wondrous Synergist", ["text"] = "2 sec cast 18 hrs cooldown – 3\n1 Charge\nTools: Philosopher's Stone\nReagents:\nStabilized Derivate (4), Tranquility Bloom (2), Sanguithorn (2), Azeroot (2), Argentleaf (2), Mana Lily (2)\nOptional Reagents:\nSpecialization:\nTransmutation Authority - Synthesis Synergy\n\nWondrous Synergist\nCrafting Reagent\n\nProvides the following property: Wondrous Synergist\n\"Created by experienced alchemists. Can be bought and sold on the Auction House.\"" }
entries[1230857] = { ["name"] = "Voidlight Potion Cauldron", ["text"] = "2 sec cast 3\nReagents:\nNocturnal Lotus , Stabilized Derivate (5), Petrified Root (4), Sunglass Vial (20), Wondrous Synergist (4)\nOptional Reagents:\nSpecialization:\nPotion Prowess (30)\n\nVoidlight Potion Cauldron\nBinds to Warband\n\nUse: Place a cauldron that allows party and raid members to take potions of their choosing from among the recipes known by your Warband. Only alchemists with the cauldron recipe will contribute.\n\nThe cauldron lasts for 5 min and has 80 charges.\n81" }
entries[1230858] = { ["name"] = "Light's Preservation", ["text"] = "2 sec cast\nReagents:\nMote of Light , Tranquility Bloom (4), Azeroot (3), Sunglass Vial (5)\nOptional Reagents:\nSpecialization:\nPotion Prowess - Path of Light\n\nUse: Conjure a shield of light that absorbs 121433 damage for 30 sec.\n81\n\"Created by experienced alchemists. Can be bought and sold on the Auction House.\"" }
entries[1230859] = { ["name"] = "Potion of Recklessness", ["text"] = "2 sec cast\nReagents:\nMote of Primal Energy , Tranquility Bloom (8), Azeroot (4), Sunglass Vial (5)\nOptional Reagents:\nVendor:\nVoid Researcher Anomander\nZone:\nVoidstorm\nCost:\n150\n1500\n\nUse: Gain 1725 of your highest secondary stat while losing 232 of your lowest secondary stat for 30 sec.\n81\n\"Created by experienced alchemists. Can be bought and sold on the Auction House.\"" }
entries[1230860] = { ["name"] = "Draught of Rampant Abandon", ["text"] = "2 sec cast\nReagents:\nMote of Primal Energy , Tranquility Bloom (8), Sanguithorn (3), Mana Lily (3), Sunglass Vial (5)\nOptional Reagents:\nDiscovery:\nCamberon's Cauldron\n\nUse: Increases Primary Stat by 774 for 30 sec. While under the effects of this potion the Void may extract its toll, opening a void zone at your feet.\n81\n\"Created by experienced alchemists. Can be bought and sold on the Auction House.\"" }
entries[1230861] = { ["name"] = "Primal Philosopher's Stone", ["text"] = "2 sec cast\nReagents:\nStabilized Derivate (2), Mote of Light (2), Refreshing Serum (5)\nOptional Reagents:\nDiscovery:\nCamberon's Cauldron\n\nPrimal Philosopher's Stone\nBinds when picked up\nUnique-EquippedTrinket\n+8 Strength\n+8 Agility\n+8 Intellect\n+ 16 Versatility\n81\n\"Required for Alchemical Transmutation.\"" }
entries[1230862] = { ["name"] = "Potion of Devoured Dreams", ["text"] = "2 sec cast\nReagents:\nMote of Wild Magic (2), Tranquility Bloom (8), Mana Lily (4), Sunglass Vial (5)\nOptional Reagents:\nDiscovery:\nCamberon's Cauldron\n\nUse: Elevate your focus to restore ( 3930 * 10) mana over 10 sec, but you are defenseless until your focus is broken.\n81\n\"Created by experienced alchemists. Can be bought and sold on the Auction House.\"" }
entries[1230863] = { ["name"] = "Potion of Zealotry", ["text"] = "2 sec cast\nReagents:\nMote of Light , Tranquility Bloom (8), Azeroot (10), Sunglass Vial (5)\nOptional Reagents:\nDiscovery:\nCamberon's Cauldron\n\nUse: For the next 30 sec your damaging abilities have a chance to deal 12251 Holy damage and mark the target with Zealotry . Zealotry increases the damage taken from Burst of Zealotry by 10%. Damaging a new target will remove Zealotry from the previous target.\n81\n\"Created by experienced alchemists. Can be bought and sold on the Auction House.\"" }
entries[1230864] = { ["name"] = "Amani Extract", ["text"] = "2 sec cast\nReagents:\nTranquility Bloom (8), Azeroot (3), Sunglass Vial (5)\nOptional Reagents:\nVendor:\nMagovu\nZone:\nZul'Aman\nCost:\n150\n1500\n\nUse: Restores ( 26543 * 10) health over 20 sec.\n81\n\"Created by experienced alchemists. Can be bought and sold on the Auction House.\"" }
entries[1230865] = { ["name"] = "Lightfused Mana Potion", ["text"] = "2 sec cast\nReagents:\nTranquility Bloom (8), Mana Lily (3), Sunglass Vial (5)\nOptional Reagents:\nDiscovery:\nCamberon's Cauldron\n\nUse: Restores 26200 mana.\n81\n\"Created by experienced alchemists. Can be bought and sold on the Auction House.\"" }
entries[1230866] = { ["name"] = "Silvermoon Health Potion", ["text"] = "2 sec cast\nReagents:\nTranquility Bloom (6), Sunglass Vial (5)\nOptional Reagents:\nProfession:\nAlchemy (1)\n\nUse: Restores 241304 health.\n81\n\"Created by experienced alchemists. Can be bought and sold on the Auction House.\"" }
entries[1230867] = { ["name"] = "Void-Shrouded Tincture", ["text"] = "2 sec cast\nReagents:\nMote of Pure Void (2), Tranquility Bloom (8), Sanguithorn (4), Sunglass Vial (5)\nOptional Reagents:\nSpecialization:\nPotion Prowess - Path of Void\n\nUse: The imbiber gains invisibility for 12-18 sec (based on crafting quality). (5 Min Cooldown)\n81\n\"Created by experienced alchemists. Can be bought and sold on the Auction House.\"" }
entries[1230868] = { ["name"] = "Refreshing Serum", ["text"] = "2 sec cast\nReagents:\nTranquility Bloom (8), Sanguithorn (3), Sunglass Vial (5)\nOptional Reagents:\nProfession Trainer:\nMidnight Alchemy (15)\nCost:\n125\n\nUse: Restores ( 202377 - 202377 %50) health and 22300 mana.\n81\n\"Created by experienced alchemists. Can be bought and sold on the Auction House.\"" }
entries[1230869] = { ["name"] = "Light's Potential", ["text"] = "2 sec cast\nReagents:\nMote of Light , Tranquility Bloom (8), Azeroot (3), Argentleaf (3), Sunglass Vial (5)\nOptional Reagents:\nDiscovery:\nCamberon's Cauldron\n\nUse: Drink to increase your primary stat by 695 for 30 sec.\n81\n\"Created by experienced alchemists. Can be bought and sold on the Auction House.\"" }
entries[1230870] = { ["name"] = "Haranir Phial of Finesse", ["text"] = "2 sec cast\nReagents:\nMote of Primal Energy (2), Tranquility Bloom (8), Azeroot (3), Mana Lily (6), Sunglass Vial (4)\nOptional Reagents:\nSpecialization:\nFluent in Flasks - Haranir Secrets\n\nUse: Drink to increase your Finesse by 45 and your Deftness by 14 .\n\nLasts 30 min and through death. Consuming an identical phial will add another 30 min.\n81\n\"Created by experienced alchemists. Can be bought and sold on the Auction House.\"" }
entries[1230872] = { ["name"] = "Haranir Phial of Ingenuity", ["text"] = "2 sec cast\nReagents:\nMote of Pure Void (2), Tranquility Bloom (8), Sanguithorn (6), Mana Lily (3), Sunglass Vial (4)\nOptional Reagents:\nDiscovery:\nCamberon's Cauldron\n\nUse: Drink to increase your Ingenuity by 45 and your Crafting Speed by 23 .\n\nLasts 30 min and through death. Consuming an identical phial will add another 30 min.\n81\n\"Created by experienced alchemists. Can be bought and sold on the Auction House.\"" }
entries[1230873] = { ["name"] = "Haranir Phial of Perception", ["text"] = "2 sec cast\nReagents:\nMote of Wild Magic (2), Tranquility Bloom (8), Azeroot (6), Argentleaf (3), Sunglass Vial (4)\nOptional Reagents:\nVendor:\nNaynar\nZone:\nHarandar\nCost:\n150\n1500\n\nUse: Drink to increase your Perception by 45 and your Deftness by 14 .\n\nLasts 30 min and through death. Consuming an identical phial will add another 30 min.\n81\n\"Created by experienced alchemists. Can be bought and sold on the Auction House.\"" }
entries[1230874] = { ["name"] = "Cauldron of Sin'dorei Flasks", ["text"] = "2 sec cast 3\nReagents:\nNocturnal Lotus , Stabilized Derivate (5), Petrified Root (4), Sunglass Vial (20), Wondrous Synergist (4)\nOptional Reagents:\nSpecialization:\nFluent in Flasks (30)\n\nCauldron of Sin'dorei Flasks\nBinds to Warband\n\nUse: Place a cauldron that allows party and raid members to take flasks of their choosing from among the recipes known by your Warband. Only alchemists with the cauldron recipe will contribute.\n\nThe cauldron lasts for 5 min and has 40 charges.\n81" }
entries[1230875] = { ["name"] = "Flask of Thalassian Resistance", ["text"] = "2 sec cast\nReagents:\nNocturnal Lotus , Mote of Light (2), Azeroot (6), Mana Lily (8), Sunglass Vial (2)\nOptional Reagents:\nSpecialization:\nFluent in Flasks - Sin'dorei Specialist\n\nUse: Increases your Versatility by 165 for 1 hour.\n\nLasts 1 hour and through death. Consuming an identical flask will add another 1 hour. (3 Sec Cooldown)\n81\n\"Created by experienced alchemists. Can be bought and sold on the Auction House.\"" }
entries[1230876] = { ["name"] = "Flask of the Magisters", ["text"] = "2 sec cast 2\nReagents:\nNocturnal Lotus , Mote of Pure Void (2), Sanguithorn (8), Mana Lily (6), Sunglass Vial (2)\nOptional Reagents:\nDiscovery:\nCamberon's Cauldron\n\nUse: Increases your Mastery by 165 for 1 hour.\n\nLasts 1 hour and through death. Consuming an identical flask will add another 1 hour. (3 Sec Cooldown)\n81\n\"Created by experienced alchemists. Can be bought and sold on the Auction House.\"" }
entries[1230877] = { ["name"] = "Flask of the Blood Knights", ["text"] = "2 sec cast 2\nReagents:\nNocturnal Lotus , Mote of Wild Magic (2), Sanguithorn (6), Argentleaf (8), Sunglass Vial (2)\nOptional Reagents:\nDiscovery:\nCamberon's Cauldron\n\nUse: Increases your Haste by 165 for 1 hour.\n\nLasts 1 hour and through death. Consuming an identical flask will add another 1 hour. (3 Sec Cooldown)\n81\n\"Created by experienced alchemists. Can be bought and sold on the Auction House.\"" }
entries[1230878] = { ["name"] = "Flask of the Shattered Sun", ["text"] = "2 sec cast 2\nReagents:\nNocturnal Lotus , Mote of Primal Energy (2), Azeroot (8), Argentleaf (6), Sunglass Vial (2)\nOptional Reagents:\nDiscovery:\nCamberon's Cauldron\n\nUse: Increases your Critical Strike by 165 for 1 hour.\n\nLasts 1 hour and through death. Consuming an identical flask will add another 1 hour. (3 Sec Cooldown)\n81\n\"Created by experienced alchemists. Can be bought and sold on the Auction House.\"" }
entries[1230883] = { ["name"] = "Vicious Thalassian Flask of Honor", ["text"] = "2 sec cast 2\nReagents:\nTranquility Bloom (6), Sanguithorn (8), Azeroot (6), Sunglass Vial (2)\nVendor:\nMirvedon\nZone:\nSilvermoon City\nCost:\n7500\n\nUse: Drink to increase honor gains by 15%. Can be used in all rated and unrated PvP environments.\n\nLasts 1 hour and through death. Consuming an identical flask will add another 1 hour. (3 Sec Cooldown)\n81\n\"Created by experienced alchemists. Can be bought and sold on the Auction House.\"" }
entries[1230885] = { ["name"] = "Magister's Alchemist Stone", ["text"] = "2 sec cast 2\nReagents:\nStabilized Derivate (5), Mote of Primal Energy (8), Mote of Wild Magic (8), Tormented Tantalum , Wondrous Synergist (2), Spark (#500) (2)\nOptional Reagents:\nSpecialization:\nTransmutation Authority (30)\n\nMagister's Alchemist Stone\nBinds when picked up\nUnique-Equipped: Alchemist Stone (1)Trinket\n+ 13 Versatility\nEquip: When you heal or deal damage you have a chance to increase your Strength, Agility, or Intellect by 35 for 15 sec. Your highest stat is always chosen.\n\nEquip: Increases the effect that healing and mana potions have on the wearer by 40%. This effect does not stack.\n80\n\"Can be used for transmutations in place of a Philosopher's Stone.\"" }
entries[1230886] = { ["name"] = "Enlightenment Tonic", ["text"] = "2 sec cast\nReagents:\nTranquility Bloom (3), Sunglass Vial (5)\nOptional Reagents:\nProfession Trainer:\nMidnight Alchemy (5)\nCost:\n125\n\nUse: Drink to slow your falling speed for 6 sec or 13 sec, depending on potion quality.\n81\n\"Created by experienced alchemists. Can be bought and sold on the Auction House.\"" }
entries[1230887] = { ["name"] = "Transmute: Mote of Wild Magic", ["text"] = "2 sec cast 18 hrs cooldown\n1 Charge\nTools: Philosopher's Stone\nReagents:\nMote of Light (10), Stabilized Derivate (2)\nOptional Reagents:\nProfession Trainer:\nMidnight Alchemy (5)\nCost:\n125\n\nMote of Wild Magic\nCrafting Reagent\n\"Wild magic given a solid form. Can be bought and sold on the Auction House.\"" }
entries[1230888] = { ["name"] = "Transmute: Mote of Pure Void", ["text"] = "2 sec cast 18 hrs cooldown\n1 Charge\nTools: Philosopher's Stone\nReagents:\nMote of Wild Magic (10), Stabilized Derivate (2)\nOptional Reagents:\nDiscovery:\nCamberon's Cauldron\n\nMote of Pure Void\nCrafting Reagent\n\"A solid orb of the nothingness that makes up the vast Twisting Nether. At least, you think it's solid. Can be bought and sold on the Auction House.\"" }
entries[1230889] = { ["name"] = "Transmute: Mote of Primal Energy", ["text"] = "2 sec cast 18 hrs cooldown\n1 Charge\nTools: Philosopher's Stone\nReagents:\nMote of Pure Void (10), Stabilized Derivate (2)\nOptional Reagents:\nDiscovery:\nCamberon's Cauldron\n\nMote of Primal Energy\nCrafting Reagent\n\"A coalesced mote of pure, primal energy. Can be bought and sold on the Auction House.\"" }
entries[1230890] = { ["name"] = "Transmute: Mote of Light", ["text"] = "2 sec cast 18 hrs cooldown\n1 Charge\nTools: Philosopher's Stone\nReagents:\nMote of Primal Energy (10), Stabilized Derivate (2)\nOptional Reagents:\nDiscovery:\nCamberon's Cauldron\n\nMote of Light\nCrafting Reagent\n\"A mote of coalesced light formed from the Lightbloom. Can be bought and sold on the Auction House.\"" }
entries[1230891] = { ["name"] = "Box of Rocks", ["text"] = "2 sec cast 18 hrs recharge\n2 Charges\nTools: Philosopher's Stone\nReagents:\nFantastic Fur (8), Stabilized Derivate , Void-Tempered Hide (18), Void-Tempered Plating (18)\nOptional Reagents:\nTransmute leather into various ores.\nSpecialization:\nTransmutation Authority\n\nBox of Rocks\nBinds when picked up\n\"Exactly what you expect. Created by experienced alchemists.\"\n<Right Click to Open>" }
entries[1230892] = { ["name"] = "Bouquet of Herbs", ["text"] = "2 sec cast 18 hrs recharge\n2 Charges\nTools: Philosopher's Stone\nReagents:\nStabilized Derivate , Eversinging Dust (20), Radiant Shard (4)\nOptional Reagents:\nDiscovery:\nCamberon's Cauldron\n\nBouquet of Herbs\nBinds when picked up\n\"A lovely bouquet of herbs from Midnight regions. Created by experienced alchemists.\"\n<Right Click to Open>" }
entries[1230893] = { ["name"] = "School of Gems", ["text"] = "2 sec cast 18 hrs recharge\n2 Charges\nTools: Philosopher's Stone\nReagents:\nEversong Trout (4), Bloomtail Minnow (12), Sin'dorei Swarmer (20), Stabilized Derivate , Composite Flora (3)\nOptional Reagents:\nDiscovery:\nCamberon's Cauldron\n\nSchool of Gems\nBinds when picked up\n\"Stuffed to the gills with gems.\"\n<Right Click to Open>" }
entries[1230898] = { ["name"] = "Lothraxion's Holy Flame", ["text"] = "40 yd range\nInstant 15 sec cooldown\nInflicts 120 Physical damage to enemies within 5 yards of the impact." }
entries[1230900] = { ["name"] = "Ethereal Energy Converter", ["text"] = "Unlimited range\nInstant\nWhen a party member drops below 60% health, an Ethereal Energy Converter materializes, dealing moderate damage to nearby enemies and taunting them for 4 sec. Once the taunt expires, the Converter releases an Etherwave healing nearby allies for 20% of their health. Can be triggered every 2 min. Killing enemies reduces the cooldown of this effect by 2 sec." }
